fn angle(a:(f32,f32),b:(f32,f32))->f32 {let v=(a.0*b.0+a.1*b.1)/((a.0*a.0+a.1*a.1)*(b.0*b.0+b.1*b.1)).sqrt();let x=v.abs();let mut omx=1.0-x;if omx<0.0 {omx=0.0} let mut r=(((((((-0.0012624911*x+0.00667009)*x-0.017088126)*x+0.03089188)*x-0.050174303)*x+0.08897899)*x-0.2145988)*x+1.5707963)*omx.sqrt();if !(v>=0.0){r=std::f32::consts::PI-r} r*(a.0*b.1-a.1*b.0).signum() }
fn main(){for (a,b) in [((3.,4.),(5.,7.)),((1e20,1e20),(1e20,-1e20)),((1e-20,1e-20),(1e-20,-1e-20)),((3.,7.),(-9.,4.))] {println!("{:?} {:?} {:08x}",a,b,angle(a,b).to_bits());}}
